#!/usr/bin/env node
// Copies the Statement Writer engine from the server to the client.
//
// The engine (schemas, compute, HTML renderer) runs in both places: the
// browser computes the live preview, the server computes everything that is
// stored or exported. The canonical copy is server/src/lib/fs/engine; the
// client copy is GENERATED by this script and must never be edited by hand.
// server/src/lib/__tests__/fsEngineSync.test.ts fails when the two differ.
//
//   node scripts/sync-fs-engine.mjs

import { cpSync, mkdirSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const from = join(root, 'server', 'src', 'lib', 'fs', 'engine');
const to = join(root, 'client', 'src', 'lib', 'fsEngine');

rmSync(to, { recursive: true, force: true });
mkdirSync(to, { recursive: true });
cpSync(from, to, { recursive: true, filter: (src) => !src.endsWith('.test.ts') });
writeFileSync(
  join(to, 'GENERATED.md'),
  '# Generated — do not edit\n\nThis directory is a copy of `server/src/lib/fs/engine`, written by\n`node scripts/sync-fs-engine.mjs`. Edit the server copy and re-run the script;\n`fsEngineSync.test.ts` fails when the two differ.\n',
);

const count = (dir) => readdirSync(dir, { withFileTypes: true })
  .reduce((n, e) => n + (e.isDirectory() ? count(join(dir, e.name)) : e.name.endsWith('.ts') ? 1 : 0), 0);
console.log(`Synced ${count(to)} engine files to client/src/lib/fsEngine`);
